LO.DAYS = [
 {title:'THE NEW HIRE',date:'Monday, October 18, 1999',weather:'A clear morning. Rain after dark.',headline:'BELLPORT PREPARES FOR HARBOR WEEK',intro:'A fresh apron. A false name. A very real lunch rush.',brief:'You are Alex Vale, a new cashier at Starline Burger. You started today. Mara Bell runs the shop. A courier may ask about the discontinued Midnight Special. That question alone does not prove who he is. Ask which side comes with it: the correct answer is “the late ferry.” The original delivery is at 6 p.m. by the west entrance. Verify any changes. Keep ordinary customers out of the operation.',memo:'STAFF MEMO — Wash your hands. Keep raw patties separate from finished food. Read back changed orders. Mara runs the shop; Mina handles the lunch crowd. The Midnight Special was removed from the menu last month.',mission:'Identify the courier, complete a discreet handoff, and report the revised delivery.',special:'nico',line:'Do you still do the Midnight Special? The one with the late ferry. There has been a change. Don’t use the west entrance. Use the east entrance at half past seven, not six. The extra invoice is for you. Please keep it off the counter.',opening:'Your application says you work well under pressure. Good. The fryer disagrees.',closing:'Funny. You remember every face, but you still forget the fries.',facts:[{id:'D1_CHANGE',title:'Delivery changed',text:'Nico said the delivery moved from 6 p.m. at the west entrance to 7:30 p.m. at the east entrance.',kind:'Witness statement',source:'Nico · spoken handoff',confirmed:true}],reportPrompt:'Write 25–60 words for Control. Explain the new delivery time and entrance, and say that the original arrangement has changed.',checks:[{id:'time',label:'The new time: 7:30 p.m.',re:'7[:.]30|seven[ -]thirty|half past seven'},{id:'place',label:'The new place: east entrance',re:'east (?:entrance|door|gate)'},{id:'change',label:'Clearly describe a change',re:'mov|chang|instead|replac|original|no longer'}],inspection:false},
 {title:'SAME AS YESTERDAY',date:'Tuesday, October 19, 1999',weather:'Low clouds. Trouble in a good coat.',headline:'NORTHLINE TRANSPORT CEASES OPERATIONS',intro:'Someone knows yesterday’s password. Someone else knows why.',brief:'Yesterday’s phrase is compromised. A visitor claims to represent Northline Transport. This morning’s public notice says that company ceased operations last Friday. Ask for paperwork and compare the dates before any handoff. Nico is still your contact. Avoid making an accusation you cannot support.',memo:'SUPPLIER NOTICE — Northline Transport ceased operations on Friday, October 15. Its old collection slips are no longer valid. Current deliveries are handled by Harbor Freight. Do not release stock without a matching invoice.',mission:'Spot the false pickup, protect the parcel, and find out what the records contain.',special:'nico',line:'The man asking for our special yesterday? I didn’t send him. His Northline slip is out of date. I thought I was moving delivery records. Those names are people—witnesses. I need someone to believe me.',opening:'The coffee machine is making that noise again. If it starts asking for a pension, unplug it.',closing:'Everybody wants to know what is in a bag. Almost nobody asks who packed it.',facts:[{id:'D2_COVER',title:'A company that no longer exists',text:'The visitor used a Northline pickup slip. The supplier notice says Northline ceased operations on October 15.',kind:'Document comparison',source:'Supplier notice + pickup slip',confirmed:true},{id:'D2_NAMES',title:'Names in the records',text:'Nico says the delivery records identify witnesses. This is his statement, not independent confirmation.',kind:'Witness statement',source:'Nico · after the false pickup',confirmed:false}],reportPrompt:'Write 30–70 words. Explain why the Northline pickup was suspicious, and distinguish what the documents show from what Nico claims.',checks:[{id:'company',label:'Northline is no longer operating',re:'northline[\\s\\S]{0,55}(?:clos|ceas|stopp|no longer|out of business)|(?:clos|ceas|no longer)[\\s\\S]{0,55}northline'},{id:'names',label:'The records contain witness identities',re:'witness|names|identit'},{id:'source',label:'Attribute the claim to Nico',re:'nico|courier (?:said|claims)|according to'}],inspection:true},
 {title:'ROUTINE INSPECTION',date:'Wednesday, October 20, 1999',weather:'Bright windows. Uncomfortable questions.',headline:'CITY SECURITY ANNOUNCES “CLEAN SLATE” OPERATION',intro:'One inspector wants the cold-storage log. Another wants your story.',brief:'Vera Quinn is the real food safety inspector. Cooperate with her inspection; a clean kitchen is part of your cover. Elias Cole is investigating a missing courier. Be accurate about what you actually saw. Your cover: Alex Vale, started Monday, manager Mara Bell. Do not confuse an inference with an observation.',memo:'COLD STORAGE — If a fridge loses power, close the door and arrange a repair. Stop using questionable stock. A written temperature does not make food safe. Keep a clear walking route and remove waste before an inspection.',mission:'Pass the hygiene check, answer Cole consistently, and establish what the transport order actually says.',special:'cole',line:'Your shift record says you started on Monday. I’m not asking what you think happened. Tell me what you actually saw. This order calls them passengers, but there are no tickets and no public route. I cannot call them prisoners without more evidence.',opening:'If this fridge is unreliable, stop using it. Writing a better temperature won’t make the food safer.',closing:'I don’t need your real name. I need to know whether you’ve brought trouble to my door.',facts:[{id:'D3_ORDER',title:'Unexplained transport order',text:'A city order lists passengers without tickets or a public route. It does not itself prove an arrest operation.',kind:'Primary document',source:'Cole · transport order',confirmed:true},{id:'D3_WITNESS',title:'What you personally observed',text:'You personally saw Nico enter the diner. His claims about the names remain statements that require corroboration.',kind:'Direct observation',source:'Your shift record',confirmed:true}],reportPrompt:'Write 30–70 words. Describe the unexplained transport, identify the source, and state what remains unconfirmed.',checks:[{id:'transport',label:'Describe the transport order',re:'transport|passenger|bus|ticket'},{id:'source',label:'Identify Cole or the order as the source',re:'cole|order|document'},{id:'uncertain',label:'Preserve uncertainty',re:'unconfirm|not (?:yet )?(?:proven|verified|confirmed)|cannot (?:yet )?confirm|may|claims|alleg'}],inspection:true},
 {title:'THE STORM SPECIAL',date:'Thursday, October 21, 1999',weather:'Heavy rain. A power warning is in effect.',headline:'STORM DISRUPTS HARBOR TRAFFIC',intro:'A restaurant can be a shelter. A receipt can be a lifeline.',brief:'Keep the shop running through the storm. A power interruption is likely: finish hot food, keep the fridge closed, and leave a clear route to the breaker. Iris has corroborating documents. Listen carefully to the distinction between what she knows and what she suspects. Control has ordered you to deliver the full names. You must decide whether that serves the people on the list.',memo:'STORM PLAN — The breaker is beside the storeroom door. Kitchen equipment cannot cook without power. Prepared drinks still work. The bus depot is rerouting vehicles; check today’s printed notice before giving directions.',mission:'Help stranded neighbors, restore power, and corroborate the transport details.',special:'iris',line:'I have copies of the original records. The charges were added later. The vehicle is leaving from depot two at seven thirty tomorrow evening, not depot four. I have not confirmed the driver. Protect the witnesses’ names; publish the altered records, not their addresses.',opening:'There’s soup in the back and exactly no soup on the menu. Today we improvise.',closing:'You’ve been collecting names. Have you asked what happens to the people attached to them?',facts:[{id:'D4_FORGED',title:'Altered records',text:'Iris compared the originals with the official files. The allegations were added later.',kind:'Corroborated documents',source:'Iris · original and altered records',confirmed:true},{id:'D4_ROUTE',title:'Friday transport',text:'The vehicle is scheduled to leave depot 2 at 7:30 p.m. on Friday. The driver has not been confirmed.',kind:'Corroborated schedule',source:'Iris · route notice',confirmed:true}],reportPrompt:'Write 35–80 words. State the depot, time, evidence of alteration, and the detail that is still unconfirmed.',checks:[{id:'depot',label:'The correct departure point: depot 2',re:'depot (?:2|two)'},{id:'time',label:'Departure: 7:30 p.m.',re:'7[:.]30|seven[ -]thirty|half past seven'},{id:'records',label:'The records were altered',re:'alter|forg|add(?:ed)? later|falsif|fabricat'},{id:'uncertain',label:'The driver is unconfirmed',re:'driver[\\s\\S]{0,40}(?:unconfirm|not|unknown)|(?:unconfirm|unknown|not verified)[\\s\\S]{0,40}driver'}],inspection:false},
 {title:'LAST ORDER',date:'Friday, October 22, 1999',weather:'The storm has passed. Harbor Week begins.',headline:'CELEBRATION TODAY; QUESTIONS REMAIN',intro:'The city is celebrating. Table four has been waiting.',brief:'The transport is scheduled for this evening. Control demands every name. Iris can publish redacted evidence. Cole can challenge the order if you give him corroboration. Nico wants the witnesses protected. Write a precise final brief, choose what to share and with whom, and keep innocent customers outside the operation.',memo:'FINAL SHIFT — Keep a short menu during the celebration rush. Never leave personal records in a public tray. A redacted report removes witness names and addresses while preserving the evidence. Your coworkers can only help with what you have actually told them.',mission:'Complete the final shift and decide where the evidence goes.',special:'nico',line:'They moved the van to depot two. Seven thirty tonight. Iris has the originals. Cole has the authority to stop it if he believes us. Control wants the list. Please don’t turn us into another delivery.',opening:'Whatever you’re about to do, finish table four first. They’ve been waiting.',closing:'Some people leave a tip. Some people leave a city different from the way they found it.',facts:[{id:'D5_CONFIRM',title:'Final confirmation',text:'Nico confirms depot 2 and 7:30 p.m. tonight. Iris holds the originals; Cole holds the official order.',kind:'Cross-checked handoff',source:'Nico + Iris + Cole',confirmed:true}],reportPrompt:'Write 35–90 words for your chosen recipient. Explain the altered records and departure, distinguish evidence from claims, and say how you will protect witness identities.',checks:[{id:'records',label:'Explain the altered records',re:'alter|forg|falsif|fabricat'},{id:'depot',label:'Include depot 2',re:'depot (?:2|two)'},{id:'time',label:'Include 7:30 p.m.',re:'7[:.]30|seven[ -]thirty|half past seven'},{id:'privacy',label:'Protect witness identities',re:'redact|withhold|protect[\\s\\S]{0,25}(?:name|identit|witness)|omit[\\s\\S]{0,20}(?:name|address)'}],inspection:true}
];
